            for (int j = i + 1; j <= s.length(); j++) {
                substrings.add(s.substring(i, j));
            }
        }
    }

    for (int size = substrings.size(); size > 0; size--) {
        for (String sub : substrings) {
            if (sub.length() >= size) {
                if (strings.stream().allMatch(s -> s.contains(sub) || s.contains(new StringBuilder(sub).reverse().toString()))) {
                    return size;
                }
            }
        }
    }

    return 0;
