/**
 * Counts the number of distinct oil deposits in the given grid.
 *
 * @param grid - A 2D character array representing the land, where '*' indicates no oil and '@' indicates an oil pocket.
 * @return The number of distinct oil deposits in the grid.
 */
public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int count = 0;
    int rows = grid.length;
    int cols = grid[0].length;

    boolean[][] visited = new boolean[rows][cols];

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                count++;
                dfs(grid, i, j, visited);
            }
        }
    }

    return count;
}

/**
 * Performs a Depth-First Search (DFS) to mark all connected oil pockets.
 *
 * @param grid - The 2D character array representing the land.
 * @param row  - The current row in the grid.
 * @param col  - The current column in the grid.
 * @param visited - A 2D boolean array to keep track of visited cells.
 */
private static void dfs(char[][] grid, int row, int col, boolean[][] visited) {
    int rows = grid.length;
    int cols = grid[0].length;

    if (row < 0 || row >= rows || col < 0 || col >= cols || grid[row][col] != '@' || visited[row][col]) {
        return;
    }

    visited[row][col] = true;

    // Explore all 8 possible directions
    dfs(grid, row - 1, col, visited);
    dfs(grid, row + 1, col, visited);
    dfs(grid, row, col - 1, visited);
    dfs(grid, row, col + 1, visited);
    dfs(grid, row - 1, col - 1, visited);
    dfs(grid, row + 1, col + 1, visited);
    dfs(grid, row - 1, col + 1, visited);
    dfs(grid, row + 1, col - 1, visited);
}

