private static void traverse(char[][] grid, int i, int j) {
    if (i < 0 || i >= grid.length || j < 0 || j >= grid[i].length || grid[i][j] != '@') {
        return;
    }
    grid[i][j] = '*'; // Mark as visited
    traverse(grid, i - 1, j);
    traverse(grid, i + 1, j);
    traverse(grid, i, j - 1);
    traverse(grid, i, j + 1);
}
