public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }

    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int depositCount = 0;

    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (grid[i][j] == '@' && !visited[i][j]) {
                bfs(grid, visited, i, j);
                depositCount++;
            }
        }
    }

    return depositCount;
}

private static void bfs(char[][] grid, boolean[][] visited, int row, int col) {
    int rows = grid.length;
    int cols = grid[0].length;
    Queue<int[]> queue = new LinkedList<>();
    queue.add(new int[]{row, col});
    visited[row][col] = true;

    int[] rowOffsets = {-1, 1, 0, 0};
    int[] colOffsets = {0, 0, -1, 1};

    while (!queue.isEmpty()) {
        int[] current = queue.poll();
        int currentRow = current[0];
        int currentCol = current[1];

        for (int k = 0; k < 4; k++) {
            int newRow = currentRow + rowOffsets[k];
            int newCol = currentCol + colOffsets[k];

            if (newRow >= 0 && newRow < rows && newCol >= 0 && newCol < cols && grid[newRow][newCol] == '@' && !visited[newRow][newCol]) {
                queue.add(new int[]{newRow, newCol});
                visited[newRow][newCol] = true;
            }
        }
    }
}

