public static int maxRegions(int N) {
    if (N == 0) {
        return 1; // The plane is not divided
    } else if (N == 1) {
        return 2; // One triangle divides the plane into 2 regions
    } else {
        return 2 + 3 * (N - 1); // Each additional triangle can intersect all previous edges, adding 3 new regions per triangle
    }
