public static String canTravelMaze(int n, int[] start, int[] end, int[][] paths) {
    boolean[][] visited = new boolean[n][n];
    boolean result = dfs(start[0], start[1], end[0], end[1], paths, visited);
    return result ? "can be travelled" : "cannot be travelled";
}

private static boolean dfs(int x, int y, int endX, int endY, int[][] paths, boolean[][] visited) {
    if (x == endX && y == endY) {
        return true;
    }
    visited[x][y] = true;
    for (int[] path : paths) {
        if (!visited[path[0]][path[1]] && (path[0] == x && path[1] == y || path[2] == x && path[3] == y)) {
            if ( DFSHelper(path[0], path[1], path[2], path[3], endX, endY, paths, visited) ) {
                return true;
            }
            if (DFSHelper(path[2], path[3], path[0], path[1], endX, endY, paths, visited)) {
                return true;
            }
        }
    }
    visited[x][y] = false;
    return false;
}

private static boolean DFSHelper(int x1, int y1, int x2, int y2, int endX, int endY, int[][] paths, boolean[][] visited) {
    int temp[] = new int[4];
    temp[0] = x1;
    temp[1] = y1;
    temp[2] = x2;
    temp[3] = y2;
    return dfs(x1, y1, endX, endY, paths, visited) || dfs(x2, y2, endX, endY, paths, visited);
}
