private static boolean dfs(int n, int current, int target, int[][] paths, boolean[] visited) {
    if (current == target) {
        return true;
    }
    visited[current] = true;
    for (int i = 0; i < n; i++) {
        if (paths[current][i] == 1 && !visited[i]) {
            if (dfs(n, i, target, paths, visited)) {
                return true;
            }
        }
    }
    visited[current] = false;
    return false;
}

