        return true;
    }
    visited[x][y] = true;
    for (int i = 0, xlim = paths.length; i < xlim; i++) {
        if (!visited[paths[i][0]][paths[i][1]] && (x == paths[i][0] && y == paths[i][1] - 1 || x == paths[i][0] && y == paths[i][1] + 1 || x == paths[i][1] - 1 && y == paths[i][0] || x == paths[i][1] + 1 && y == paths[i][0])) {
            if (dfs(paths[i][0], paths[i][1], endX, endY, visited, paths)) {
                return true;
            }
        }
    }
    visited[x][y] = false;
    return false;
}
