}

private static boolean canTravelPath(boolean[][] grid, int startX, int startY, int endX, int endY) {
    if (startX == endX && startY == endY) {
        return true;
    }
    if (startX < 0 || startX >= grid.length || startY < 0 || startY >= grid[0].length || !grid[startX][startY]) {
        return false;
    }
    grid[startX][startY] = false; // Mark as visited
    return canTravelPath(grid, startX - 1, startY, endX, endY) ||
           canTravelPath(grid, startX + 1, startY, endX, endY) ||
           canTravelPath(grid, startX, startY - 1, endX, endY) ||
           canTravelPath(grid, startX, startY + 1, endX, endY);
}
