public class DateConverter {
    public static String convertDatesToWeekdays(String date) {
        SimpleDateFormat inputFormat = new SimpleDateFormat("MM dd yyyy", Locale.ENGLISH);
        SimpleDateFormat outputFormat = new SimpleDateFormat("MMMM dd, yyyy", Locale.ENGLISH);
        Calendar calendar = Calendar.getInstance();

        try {
            Date parsedDate = inputFormat.parse(date);
            calendar.setTime(parsedDate);

            String weekday = calendar.getDisplayName(Calendar.DAY_OF_WEEK, Calendar.LONG, Locale.ENGLISH);
            return outputFormat.format(parsedDate) + " is a " + weekday;
        } catch (ParseException e) {
            e.printStackTrace();
            return "Invalid date format";
        }
    }

    public static void main(String[] args) {
        System.out.println(convertDatesToWeekdays("11 15 1997"));
        System.out.println(convertDatesToWeekdays("01 01 2000"));
        System.out.println(convertDatesToWeekdays("07 04 1998"));
    }
}
