import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class Solution {
    public int minTime(int n, int[][] edges, boolean[] hasApple) {
        Map<Integer, List<Integer>> tree = new HashMap<>();
        for (int[] edge : edges) {
            tree.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
            tree.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
        }
        return findTime(tree, hasApple, 0, -1) * 2;
    }

    private int findTime(Map<Integer, List<Integer>> tree, boolean[] hasApple, int node, int parent) {
        int time = 0;
        for (int child : tree.get(node)) {
            if (child == parent) continue;
            int childTime = findTime(tree, hasApple, child, node);
            if (childTime > 0 || hasApple[child]) {
                time += childTime + 2;
            }
        }
        return time;
    }
}
