    for (int i = 0; i < n; i++) {
        tree.add(new ArrayList<>());
    }

    for (int[] edge : edges) {
        tree.get(edge[0]).add(edge[1]);
        tree.get(edge[1]).add(edge[0]);
    }

    boolean[] visited = new boolean[n];
    return dfs(0, tree, hasApple, visited);
}

private int dfs(int node, List<List<Integer>> tree, boolean[] hasApple, boolean[] visited) {
    if (visited[node]) {
        return 0;
    }

    visited[node] = true;
    int totalTime = 0;

    for (int neighbor : tree.get(node)) {
        totalTime += dfs(neighbor, tree, hasApple, visited);
    }

    if (totalTime > 0 || hasApple[node]) {
        totalTime += 2;
    }

    return totalTime;
}
