public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    if (n <= 1) {
        return false;
    }
    double totalSum = 0;
    for (int num : nums) {
        totalSum += num;
    }
    for (int i = 1; i <= n / 2; i++) {
        Set<Double> sums = new HashSet<>();
        boolean found = false;
        for (int j = 0; j < 1 << i; j++) {
            double sum = 0;
            for (int k = 0; k < i; k++) {
                if ((j & (1 << k)) != 0) {
                    sum += nums[k];
                }
            }
            if (sum * (n - i) == (totalSum - sum) * i) {
                found = true;
            }
            sums.add(sum);
        }
        if (found) {
            return true;
        }
    }
    return false;
}
