public boolean splitArraySameAverage(int[] nums) {
    int total = 0;
    for (int num : nums) {
        total += num;
    }
    int n = nums.length;
    boolean[][] possible = new boolean[n + 1][total + 1];
    possible[0][0] = true;

    for (int i = 0; i < n; i++) {
        for (int sum = total; sum >= nums[i]; sum--) {
            for (int count = Math.min(i, sum / nums[i]); count >= 1; count--) {
                possible[i + 1][sum] = possible[i + 1][sum] || possible[i][sum - nums[i] * count];
            }
        }
    }

    for (int i = 1; i <= n / 2; i++) {
        for (int sum = nums[i - 1]; sum <= total; sum++) {
            if (sum * n == i * total && possible[i][sum]) {
                return true;
            }
        }
    }

    return false;
}
