public boolean splitArraySameAverage(int[] nums) {
    int n = nums.length;
    double sum = 0;
    for (int num : nums) {
        sum += num;
    }
    for (int i = 1; i <= n / 2; i++) {
        for (Set<Integer> set : getSubsets(nums, i)) {
            double average = Arrays.stream(set.toArray(new Integer[0])).sum() / (double) i;
            if (average * n == sum) {
                return true;
            }
        }
    }
    return false;
}

public Set<Set<Integer>> getSubsets(int[] nums, int k) {
    Set<Set<Integer>> subsets = new HashSet<>();
    backtrack(subsets, new ArrayList<>(), nums, k, 0);
    return subsets;
}

public void backtrack(Set<Set<Integer>> subsets, List<Integer> current, int[] nums, int k, int start) {
    if (current.size() == k) {
        subsets.add(new HashSet<>(current));
        return;
    }
    for (int i = start; i < nums.length; i++) {
        current.add(nums[i]);
        backtrack(subsets, current, nums, k, i + 1);
        current.remove(current.size() - 1);
    }
}
