public boolean splitArraySameAverage(int[] nums) {
    int sum = 0;
    for (int num : nums) {
        sum += num;
    }
    int n = nums.length;
    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0 && hasSubsetWithSum(nums, i, sum * i / n)) {
            return true;
        }
    }
    return false;
}

private boolean hasSubsetWithSum(int[] nums, int k, int target) {
    return subsetSum(nums, k, target, 0, 0);
}

private boolean subsetSum(int[] nums, int k, int target, int start, int currentSum) {
    if (k == 0) {
        return target == currentSum;
    }
    if (nums.length - start < k) {
        return false;
    }
    if (currentSum + nums[start] > target) {
        return subsetSum(nums, k, target, start + 1, currentSum);
    }
    return subsetSum(nums, k, target, start + 1, currentSum) ||
           subsetSum(nums, k - 1, target, start + 1, currentSum + nums[start]);
}
