public boolean splitArraySameAverage(int[] A) {
    int n = A.length;
    int sum = 0;
    for (int a : A) sum += a;
    if (sum == 0) return true;

    for (int i = 1; i <= n / 2; i++) {
        if (sum * i % n == 0) {
            if (containsSum(A, i, sum * i / n)) return true;
        }
    }
    return false;
}

private boolean containsSum(int[] A, int k, int target) {
    boolean[] dp = new boolean[target + 1];
    dp[0] = true;
    for (int a : A) {
        for (int i = target; i >= a; i--) {
            dp[i] = dp[i] || dp[i - a];
        }
    }
    return dp[target];
}
