public int minInsertions(String s) {
    int open = 0;
    int close = 0;
    int result = 0;

    for (char c : s.toCharArray()) {
        if (c == '(') {
            if (close % 2 != 0) {
                result++;
                close--;
            }
            open++;
        } else {
            close++;
            if (close > open) {
                result++;
                open++;
