public int minInsertions(String s) {
    int balance = 0; // Tracks the balance of parentheses
    int insertions = 0; // Tracks the number of insertions needed
    int i = 0;

    while (i < s.length()) {
        if (s.charAt(i) == '(') {
            balance++;
            i++;
        } else if (s.charAt(i) == ')') {
            if (i + 1 < s.length() && s.charAt(i + 1) == ')') {
                if (balance > 0) {
                    balance--;
                } else {
                    insertions++;
                }
                i += 2;
            } else {
                if (balance > 0) {
                    balance--;
                    insertions++;
                } else {
                    insertions += 2;
                }
                i++;
            }
        }
    }

    return insertions + balance * 2;
}
