/**
 * Finds the single number that appears only once in an array where every other number appears three times.
 * 
 * @param nums An integer array where every element appears three times except for one.
 * @return The element that appears only once.
 */
public static int singleNumber(int[] nums) {
    int[] count = new int[32]; // To track the count of set bits at each position
    for (int num : nums) {
        for (int i = 0; i < 32; i++) {
            count[i] += (num >> i) & 1;
        }
    }
    int result = 0;
    for (int i = 0; i < 32; i++) {
        if (count[i] % 3 != 0) {
            result |= (1 << i);
        }
    }
    return result;
}

