public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return 0;
    }

    int m = mat.length;
    int n = mat[0].length;
    int maxLength = 0;

    // Initialize 4 arrays to keep track of horizontal, vertical, diagonal, and anti-diagonal lengths
    int[][] horizontal = new int[m][n];
    int[][] vertical = new int[m][n];
    int[][] diagonal = new int[m][n];
    int[][] antiDiagonal = new int[m][n];

    for (int i = 0; i < m; i++) {
        for (int j = 0; j < n; j++) {
            if (mat[i][j] == 1) {
                // Update horizontal length if current cell is part of a continuous line of 1s
                horizontal[i][j] = (j > 0) ? horizontal[i][j - 1] + 1 : 1;
                // Update vertical length if current cell is part of a continuous line of 1s
                vertical[i][j] = (i > 0) ? vertical[i - 1][j] + 1 : 1;
                // Update diagonal length if current cell is part of a continuous line of 1s
                diagonal[i][j] = (i > 0 && j > 0) ? diagonal[i - 1][j - 1] + 1 : 1;
                // Update anti-diagonal length if current cell is part of a continuous line of 1s
                antiDiagonal[i][j] = (i > 0 && j < n - 1) ? antiDiagonal[i - 1][j + 1] + 1 : 1;

                // Check the maximum length in the four directions
                maxLength = Math.max(maxLength, horizontal[i][j]);
                maxLength = Math.max(maxLength, vertical[i][j]);
                maxLength = Math.max(maxLength, diagonal[i][j]);
                maxLength = Math.max(maxLength, antiDiagonal[i][j]);
            }
        }
    }

    return maxLength;
}
