    int n = mat[0].length;
    int maxLength = 0;

    int[][][] directions = {
        { {0, 1}, {0, 0} },  // Horizontal
        { {1, 0}, {0, 0} },  // Vertical
        { {1, 1}, {0, 0} },  // Diagonal
