                for (int[][] direction : directions) {
                    int length = 1;
                    int di = direction[0][0];
                    int dj = direction[0][1];
                    boolean isStart = true;

                    while (i + di >= 0 && i + di < m && j + dj >= 0 && j + dj < n) {
                        if (mat[i + di][j + dj] == 1 && isStart) {
                            di += direction[1][0];
                            dj += direction[1][1];
                            isStart = false;
                        } else if (mat[i + di][j + dj] == 1) {
                            length++;
                            di += direction[1][0];
                            dj += direction[1][1];
                        } else {
                            break;
                        }
                    }
                    maxLength = Math.max(maxLength, length);
                }
            }
        }
    }

    return maxLength;
