import java.util.HashMap;
import java.util.Map;

public class SquarePermutations {
    public static int squarePermutations(int[] A) {
        if (A == null || A.length == 0) {
            return 0;
        }

        Map<Integer, Integer> cache = new HashMap<>();
        return permute(A, 0, cache);
    }

    private static int permute(int[] A, int start, Map<Integer, Integer> cache) {
        if (start == A.length - 1) {
            return 1;
        }

        int key = start << 16;
        if (cache.containsKey(key)) {
            return cache.get(key);
        }

        int count = 0;
        for (int i = start + 1; i < A.length; i++) {
            int sum = A[start] + A[i];
            if (isPerfectSquare(sum)) {
                int temp = A[i];
                A[i] = A[start + 1];
                A[start + 1] = temp;

                count += permute(A, start + 1, cache);

                temp = A[i];
                A[i] = A[start + 1];
                A[start + 1] = temp;
            }
        }

        cache.put(key, count);
        return count;
    }

    private static boolean isPerfectSquare(int num) {
        int root = (int) Math.sqrt(num);
        return (root * root == num);
    }

    public static void main(String[] args) {
        System.out.println(squarePermutations(new int[]{1, 17, 8})); // Output: 2
        System.out.println(squarePermutations(new int[]{2, 2, 2})); // Output: 1
    }
}
