import java.util.HashMap;
import java.util.Map;

public class SquarePermutations {

    public static int squarePermutations(int[] A) {
        return backtrack(A, 0, new HashMap<>());
    }

    private static int backtrack(int[] A, int index, Map<Integer, Integer> count) {
        if (index == A.length) {
            return 1;
        }

        int key = index;
        if (!count.containsKey(key)) {
            count.put(key, 0);
        }

        int total = 0;
        for (int i = index; i < A.length; i++) {
            if (isPerfectSquare(A[index] + A[i])) {
                char swapTemp = (char) A[i];
                A[i] = A[index];
                A[index] = (char) swapTemp;
                total += backtrack(A, index + 1, count);
                swapTemp = (char) A[i];
                A[i] = A[index];
                A[index] = (char) swapTemp;
            }
        }

        return total;
    }

    private static boolean isPerfectSquare(int sum) {
        int root = (int) Math.sqrt(sum);
        return sum == root * root;
    }

    public static void main(String[] args) {
        System.out.println(squarePermutations(new int[]{1, 17, 8})); // Output: 2
        System.out.println(squarePermutations(new int[]{2, 2, 2})); // Output: 1
    }
}
