    int index = 0;

    for (int d = 0; d < rows + cols - 1; d++) {
        if (d % 2 == 0) {
            for (int i = Math.min(d, rows - 1); i >= Math.max(0, d - cols + 1); i--) {
                result[index++] = mat[i][d - i];
            }
        } else {
            for (int i = Math.min(d, cols - 1); i >= Math.max(0, d - rows + 1); i--) {
                result[index++] = mat[d - i][i];
            }
        }
    }

    return result;
}

