import java.util.ArrayList;
import java.util.List;

public class CenterSymmetricNumbers {

    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n <= 0) {
            return result;
        }
        backtrack(result, new char[n], 0, n - 1);
        return result;
    }

    private static void backtrack(List<String> result, char[] current, int left, int right) {
        if (left > right) {
            result.add(new String(current));
            return;
        }
        char[] pairs = {'0', '1', '6', '8', '9'};
        if (left == right) {
            for (char c : pairs) {
                if (c == '0' && current.length > 1) {
                    continue;
                }
                current[left] = c;
                result.add(new String(current));
            }
            return;
        }
        for (char c : pairs) {
            if (c == '0' && left == 0) {
                continue;
            }
            if ((c == '6' || c == '9') && left == right - 1) {
                continue;
            }
            current[left] = c;
            current[right] = c == '6' ? '9' : (c == '9' ? '6' : c);
            backtrack(result, current, left + 1, right - 1);
        }
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: [11, 69, 88, 96]
        System.out.println(centerSymmetricNumbers(1)); // Output: [0, 1, 8]
    }
}
