public class CenterSymmetricNumbers {
    public static List<String> centerSymmetricNumbers(int n) {
        if (n == 0) {
            return new ArrayList<>();
        }
        if (n == 1) {
            return new ArrayList<>(Set.of("0", "1", "8"));
        }

        Set<String> result = new HashSet<>();
        char[] symmetricPairs = {'0', '1', '8', '6', '9'};
        backtrack(result, new char[n], 0, n - 1, symmetricPairs);
        return new ArrayList<>(result);
    }

    private static void backtrack(Set<String> result, char[] current, int left, int right, char[] pairs) {
        if (left > right) {
            result.add(String.valueOf(current));
            return;
        }
        for (char p : pairs) {
            if (left == 0 && p == '0') continue; // Skip leading zero
            current[left] = p;
            current[right] = getSymmetricPair(p);
            backtrack(result, current, left + 1, right - 1, pairs);
        }
    }

    private static char getSymmetricPair(char c) {
        if (c == '6') return '9';
        if (c == '9') return '6';
        return c;
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: ["11","69","88","96"]
        System.out.println(centerSymmetricNumbers(1)); // Output: ["0","1","8"]
    }
