import java.util.ArrayList;
import java.util.List;

public class CenterSymmetricNumbers {

    public static List<String> centerSymmetricNumbers(int n) {
        List<String> result = new ArrayList<>();
        if (n == 0) {
            return result;
        }
        if (n == 1) {
            return List.of("0", "1", "8");
        }
        char[] half = new char[n / 2];
        generateSymmetricNumbers(n, half, 0, result);
        return result;
    }

    private static void generateSymmetricNumbers(int n, char[] half, int start, List<String> result) {
        if (start == half.length / 2) {
            String mid = n % 2 == 0 ? "" : String.valueOf(n / 2);
            String symmetric = buildSymmetricString(half, mid);
            result.add(symmetric);
            return;
        }
        for (int i = 0; i < 5; i++) {
            if (i == 0 && start == 0) continue; // Avoid leading zero
            half[start] = (char) ('0' + i);
            if (i != 0 || start != 0) { // Avoid odd number in the middle for n % 2 != 0
                half[half.length - 1 - start] = (char) ('0' + i);
                generateSymmetricNumbers(n, half, start + 1, result);
            }
        }
    }

    private static String buildSymmetricString(char[] half, String mid) {
        StringBuilder sb = new StringBuilder();
        sb.append(half);
        sb.append(mid);
        for (int i = half.length - 1; i >= 0; i--) {
            sb.append(half[i]);
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        List<String> result = centerSymmetricNumbers(2);
        System.out.println(result); // Output: ["11", "69", "88", "96"]

        result = centerSymmetricNumbers(1);
        System.out.println(result); // Output: ["0", "1", "8"]
    }
}
