import java.util.ArrayList;
import java.util.List;

public class CenterSymmetricNumbers {
    public static List<String> centerSymmetricNumbers(int n) {
        if (n == 0) return new ArrayList<>();
        if (n == 1) return new ArrayList<>(List.of("0", "1", "8"));

        char[] choices = new char[]{'0', '1', '6', '8', '9'};
        List<String> result = new ArrayList<>();
        helper(result, "", choices, n, n);
        return result;
    }

    private static void helper(List<String> result, String prefix, char[] choices, int n, int m) {
        if (n == 0) {
            if (prefix.charAt(0) != '0' || prefix.length() == 1) {
                result.add(prefix);
            }
            return;
        }
        if (n < m) {
            helper(result, prefix + '0', choices, n - 1, m);
        }
        for (char c : choices) {
            if (n == m && c == '0') continue;
            helper(result, c + prefix + convert(c), choices, n - 1, m);
        }
    }

    private static char convert(char c) {
        if (c == '6') return '9';
        if (c == '9') return '6';
        return c;
    }

    public static void main(String[] args) {
        System.out.println(centerSymmetricNumbers(2)); // Output: [11, 69, 88, 96]
        System.out.println(centerSymmetricNumbers(1)); // Output: [0, 1, 8]
    }
}
