public static int calculateUniqueSum(int[] nums) {
    int sum = 0;
    Set<Integer> seen = new HashSet<>();
    Set<Integer> duplicates = new HashSet<>();

    for (int num : nums) {
        if (seen.contains(num)) {
            duplicates.add(num);
        } else {
            seen.add(num);
        }
    }

    for (int num : nums) {
        if (!duplicates.contains(num)) {
            sum += num;
        }
    }

    return sum;
}
